create table vendor_contracts (end_date date not null, monthly_payment numeric(12,2) not null, start_date date not null, created_at timestamp(6), id bigint generated by default as identity, vendor_id bigint not null, attachment_url varchar(255), status varchar(255) not null check ((status in ('ACTIVE','EXPIRED','TERMINATED','UNDER_REVIEW'))), title varchar(255) not null, primary key (id));
alter table if exists vendor_contracts add constraint FKa5iua5qd0uremyurrcb3m7a40 foreign key (vendor_id) references vendors;
